// action catalog: route index, permission category, patient-scoped
const CATALOG = {
  'journey_agent/get_journey':            { route: 0,  cat: 'journey',     needs: 'patient_id' },
  'queue_agent/get_queue_status':         { route: 1,  cat: 'queue',       needs: 'department' },
  'appointment_agent/search_doctors':     { route: 2,  cat: 'appointment', needs: '' },
