  'radiology_agent/get_imaging_status':   { route: 5,  cat: 'clinical',    needs: '' },
  'pharmacy_agent/get_pharmacy_status':   { route: 6,  cat: 'pharmacy',    needs: 'patient_id' },
  'billing_agent/get_billing_status':     { route: 7,  cat: 'billing',     needs: 'patient_id' },
  'insurance_agent/get_insurance_status': { route: 8,  cat: 'insurance',   needs: 'patient_id' },
  'discharge_agent/get_discharge_status': { route: 9,  cat: 'discharge',   needs: 'patient_id' },
  'bed_agent/get_bed_status':             { route: 10, cat: 'bed',         needs: '' },
  'resource_agent/get_resources':         { route: 10, cat: 'bed',         needs: '' },
  'nursing_agent/get_nursing_tasks':      { route: 11, cat: 'nursing',     needs: 'nurse_ref' },
  'bottleneck_agent/get_bottlenecks':     { route: 12, cat: 'bottleneck',  needs: '' },
  'operations_agent/get_operations_summary': { route: 13, cat: 'operations', needs: '' },
  'finance_agent/get_finance_summary':    { route: 14, cat: 'finance',     needs: '' },
  'operations_agent/get_agent_activity':  { route: 15, cat: 'activity',    needs: '' }
};
const ALL_NON_FINANCE = ['journey','queue','appointment','clinical','pharmacy','billing','insurance','discharge','bed','nursing','bottleneck','operations','activity'];
const ROLE_CATS = {
  patient:    ['journey','queue','appointment','pharmacy','billing','insurance','discharge'],
  nurse:      ['journey','queue','appointment','clinical','pharmacy','discharge','bed','nursing','bottleneck'],
  doctor:     ['journey','queue','appointment','clinical','pharmacy','discharge','bed','bottleneck'],
  operations: ALL_NON_FINANCE,
  admin:      ALL_NON_FINANCE.concat(['finance']),
  finance:    ['finance','billing','insurance']
};
const ERP_CATS = ['billing','insurance','finance','pharmacy'];

const key = req.to_agent + '/' + req.requested_action;
const entry = CATALOG[key];
let decision = 'allowed';
let reason = '';
let result = {};
if (!entry) {
  decision = 'error';
  reason = 'unknown action ' + key;
  result = { reason: reason, supported_actions: Object.keys(CATALOG) };
} else {
  const allowedCats = ROLE_CATS[req.user_role];
  if (!allowedCats) {
    decision = 'forbidden';
    reason = 'unknown or missing user_role "' + req.user_role + '"';
  } else if (allowedCats.indexOf(entry.cat) === -1) {
    decision = 'forbidden';
    reason = 'role ' + req.user_role + ' may not use ' + key + (entry.cat === 'finance' ? ' (finance data restricted to admin/finance)' : '');
  } else if (req.user_role === 'patient') {
    const self = req.user_ref.toUpperCase();
    if (!self) { decision = 'forbidden'; reason = 'patient identity (user_ref) missing'; }
    else if (req.patient_id && req.patient_id !== self) { decision = 'forbidden'; reason = 'patients may only access their own records'; }
    else { req.patient_id = self; }
  }
  if (decision === 'allowed') {
    if (entry.needs === 'doctor_id' && !req.doctor_id && req.user_role === 'doctor') req.doctor_id = req.user_ref.toUpperCase();
    if (entry.needs === 'nurse_ref' && !req.user_ref) { decision = 'error'; reason = 'user_ref (nurse id) required'; }
    if (entry.needs === 'patient_id' && !req.patient_id) { decision = 'error'; reason = 'patient_id required'; }
    if (entry.needs === 'department' && !req.department) { decision = 'error'; reason = 'department required'; }
    if (entry.needs === 'doctor_id' && !req.doctor_id) { decision = 'error'; reason = 'doctor_id required'; }
    if (entry.needs === 'patient_or_doctor' && !req.patient_id && !req.doctor_id) { decision = 'error'; reason = 'patient_id or doctor_id required'; }
    if (decision === 'error') result = { reason: reason };
  }
  if (decision === 'forbidden') result = { reason: reason };
