req.reason = reason;
req.rejection_result = result;
req.category = entry ? entry.cat : '';
req.system = entry && ERP_CATS.indexOf(entry.cat) !== -1 ? 'suvarna_erp' : 'careos_data_layer';
req.route = decision === 'allowed' ? entry.route : 16;
return [{ json: req }];

const req = $('Check Permissions').first().json;
