const label = (t) => { const base = String(t || '').replace(/_COMPLETED$|_BOOKED$/, ''); return base.split('_').map(w => w === 'MRI' || w === 'CT' || w === 'ICU' ? w : w.charAt(0) + w.slice(1).toLowerCase()).join(' '); };
const queueEstimate = (q, ahead) => Math.ceil(ahead * (q.avg_consult_minutes || 0) / Math.max(q.active_doctors || 0, 1)) + (q.current_delay_minutes || 0);
