    if (!doc) { status = 'not_found'; result = { reason: 'doctor ' + req.doctor_id + ' not found' }; summary = result.reason; break; }
    const patients = rows('Doctor: Get Patients', 'patient_id').map(p => ({ patient_id: p.patient_id, patient_name: p.patient_name, current_stage: p.current_stage, admission_status: p.admission_status, bed_id: p.bed_id }));
    const pendingReviews = rows('Doctor: Get Diagnostics', 'order_id').filter(d => d.review_status === 'pending').map(d => ({ order_id: d.order_id, patient_id: d.patient_id, test_name: d.test_name, status: d.status, completed_at: d.completed_at, waiting_hours: hoursSince(d.completed_at) }));
