    result = { doctor: { doctor_id: doc.doctor_id, doctor_name: doc.doctor_name, department: doc.department, status: doc.status, shift: doc.shift_start + '-' + doc.shift_end }, patients: patients, pending_reviews: pendingReviews, appointments_date: day, appointments: appts };
