    if (!orders.length) { status = 'not_found'; result = { reason: 'no ' + (req.to_agent === 'lab_agent' ? 'lab' : 'imaging') + ' orders found' + (req.patient_id ? ' for ' + req.patient_id : '') }; summary = result.reason; break; }
    const withTat = orders.map(o => Object.assign({}, o, { turnaround_hours: (o.ordered_at && o.completed_at) ? Math.round((new Date(o.completed_at) - new Date(o.ordered_at)) / 36e5 * 10) / 10 : null, review_wait_hours: (o.review_status === 'pending' && o.completed_at) ? hoursSince(o.completed_at) : null }));
    const tats = withTat.map(o => o.turnaround_hours).filter(v => v !== null);
    result = { category: req.to_agent === 'lab_agent' ? 'lab' : 'imaging', orders: withTat, by_status: countBy(withTat, o => o.status), pending_reviews: withTat.filter(o => o.review_status === 'pending').map(o => ({ order_id: o.order_id, patient_id: o.patient_id, test_name: o.test_name, ordering_doctor_id: o.ordering_doctor_id, review_wait_hours: o.review_wait_hours })), avg_turnaround_hours: tats.length ? Math.round(tats.reduce((a, b) => a + b, 0) / tats.length * 10) / 10 : null };
